"""Self-contained, escaped HTML evidence viewer. No remote assets or scripts."""
from html import escape


def render(result: dict) -> str:
    esc = lambda value: escape(str(value), quote=True)
    before, after = result["transfer_before"], result["transfer_after"]
    cards = "".join(
        f'<article class="attempt {"good" if gate["accepted"] else "bad"}"><span>{"BEWAARD" if gate["accepted"] else "AFGEWEZEN"}</span><h3>{esc(gate["candidate"])}</h3><p>{esc(gate["reason"])}</p><small>{len(gate["regressions"])} regressies · {gate["gain"]:+d} extra juiste kwalificatiegevallen</small></article>'
        for gate in result["attempts"]
    )
    rows = ""
    for old, new in zip(before["rows"], after["rows"], strict=True):
        changed = old["passed"] != new["passed"]
        rows += f'<tr data-changed="{str(changed).lower()}"><td>{esc(new["id"])}</td><td class="mono">{esc(new["input"]["value"])}</td><td>{esc(new["expected_cents"])}</td><td class="{ "ok" if old["passed"] else "fail" }">{esc(old["predicted_cents"])}</td><td class="{ "ok" if new["passed"] else "fail" }">{esc(new["predicted_cents"])}</td></tr>'
    limitations = "".join(f"<li>{esc(item)}</li>" for item in result["limitations"])
    return f'''<!doctype html>
<html lang="nl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Experience Forge — de leerlus zichtbaar</title>
<style>
:root{{--bg:#f4f4ef;--ink:#202c29;--muted:#65726c;--green:#245e45;--line:#d8ded7}}
*{{box-sizing:border-box}}body{{margin:0;background:var(--bg);color:var(--ink);font:16px/1.55 system-ui,sans-serif}}main{{max-width:1100px;margin:auto;padding:35px 25px 65px}}header{{display:flex;justify-content:space-between;gap:16px;align-items:center;border-bottom:1px solid var(--line);padding-bottom:16px}}.brand{{font-weight:750;letter-spacing:-.04em;font-size:23px}}.badge{{background:#e0eadf;color:var(--green);border-radius:20px;padding:5px 12px;font-size:12px}}.eyebrow{{color:var(--green);font-size:12px;letter-spacing:.15em;text-transform:uppercase;font-weight:700}}h1{{font-size:clamp(34px,5vw,62px);line-height:1.09;letter-spacing:-.045em;max-width:820px;margin:14px 0 24px}}.intro{{max-width:730px;font-size:19px;color:var(--muted)}}.hero{{padding:46px 0 24px}}.stats{{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin:22px 0 38px}}.stat{{border:1px solid var(--line);background:#fff;padding:22px;border-radius:12px}}.stat strong{{font-size:40px;letter-spacing:-.04em;display:block}}.stat p{{margin:0;color:var(--muted);font-size:13px}}h2{{font-size:24px;letter-spacing:-.025em;margin:34px 0 16px}}.steps{{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}}.step{{padding:17px;border-top:3px solid var(--green);background:#e9eee7;border-radius:0 0 8px 8px}}.step strong{{display:block}}.step p{{font-size:13px;margin-bottom:0;color:var(--muted)}}.attempts{{display:grid;grid-template-columns:repeat(2,1fr);gap:12px}}.attempt{{border:1px solid var(--line);padding:19px;background:white;border-radius:10px}}.attempt span{{font-size:11px;letter-spacing:.1em;font-weight:700}}.bad span,.fail{{color:#a24a37}}.good span,.ok{{color:var(--green)}}.good{{border-color:#66967a;background:#eef5eb}}.attempt h3{{font-size:19px;margin:8px 0}}.attempt p{{margin:4px 0 12px}}small{{color:var(--muted)}}.rule{{background:var(--ink);color:#f4f4ef;border-radius:10px;padding:23px;font:16px/1.65 ui-monospace,monospace}}.table-wrap{{overflow-x:auto;background:#fff;border:1px solid var(--line);border-radius:10px}}table{{border-collapse:collapse;width:100%;font-size:13px}}th,td{{text-align:left;padding:11px 13px;border-bottom:1px solid #edf0e9;white-space:nowrap}}th{{background:#e9eee7;font-size:12px}}.mono{{font-family:ui-monospace,monospace}}button{{background:var(--green);color:white;border:0;border-radius:7px;padding:10px 15px;cursor:pointer;font:inherit;font-size:13px;margin-bottom:12px}}button:focus-visible,summary:focus-visible{{outline:3px solid #a85a21;outline-offset:3px}}details{{margin-top:22px;border:1px solid var(--line);padding:15px;border-radius:10px}}summary{{cursor:pointer;font-weight:600}}li{{margin:7px 0}}footer{{font-size:12px;color:var(--muted);margin-top:30px;overflow-wrap:anywhere}}@media(max-width:650px){{main{{padding:22px 16px}}header{{align-items:flex-start}}.stats{{grid-template-columns:1fr}}.stat strong{{font-size:32px}}.steps,.attempts{{grid-template-columns:1fr}}.intro{{font-size:17px}}h1{{font-size:38px}}}}
</style></head><body><main>
<header><div class="brand">Experience Forge<span style="color:#65726c;font-weight:400"> / 0.1</span></div><span class="badge">Lokaal · 0 modelaanroepen</span></header>
<section class="hero"><p class="eyebrow">Ervaring → toetsbare vaardigheid</p><h1>Een fout is pas een les<br>als de verbetering werkt.</h1><p class="intro">Deze kleine demonstratie leidt een leesregel af uit twaalf fouten. Nieuwe voorbeelden toetsen de regel. Een afzonderlijke eindtest meet of de gekozen vaardigheid ook bij andere bronnen helpt.</p></section>
<div class="stats"><article class="stat"><strong>{before["correct"]}/{before["total"]} → {after["correct"]}/{after["total"]}</strong><p>Juiste antwoorden op de afzonderlijke eindtest</p></article><article class="stat"><strong>{sum(not x["accepted"] for x in result["attempts"])}</strong><p>Te brede of verkeerd afgebakende regels afgewezen</p></article><article class="stat"><strong>{"Ja" if result["restart_verified"] else "Nee"}</strong><p>Gekozen vaardigheid blijft behouden na herstart</p></article></div>
<h2>Wat er daadwerkelijk gebeurt</h2><div class="steps"><article class="step"><strong>01 · Ervaren</strong><p>Een eenvoudig programma leest komma-decimalen verkeerd. Gelabelde uitkomsten worden lokaal opgeslagen.</p></article><article class="step"><strong>02 · Afleiden</strong><p>Een zoekalgoritme vergelijkt vier regels uit een vooraf vastgelegde, beperkte regeltaal.</p></article><article class="step"><strong>03 · Tegenspreken</strong><p>Andere voorbeelden ontdekken te brede regels en regressies. Alleen een aantoonbare verbetering wordt bewaard.</p></article><article class="step"><strong>04 · Overdragen</strong><p>Pas na selectie volgt de eindtest met nieuwe bronnen. Die labels bepalen de selectie niet.</p></article></div>
<h2>De kandidaten en hun bewijs</h2><div class="attempts">{cards}</div><h2>De bewaarde vaardigheid</h2><div class="rule">{esc(result["learned_rule"])}</div>
<h2>Controleer de eindtest zelf</h2><p>Alle getallen zijn synthetisch. Uitkomsten staan in honderdsten; <code>None</code> betekent dat het programma geen getal retourneert.</p><button id="filter" type="button" aria-pressed="false">Toon alleen verbeterde gevallen</button><div class="table-wrap"><table><thead><tr><th>Geval</th><th>Invoer</th><th>Verwacht</th><th>Voor leren</th><th>Na leren</th></tr></thead><tbody>{rows}</tbody></table></div>
<details open><summary>Wat deze demonstratie wel en niet bewijst</summary><p>Ze toont leren binnen een kleine, vooraf ontworpen regeltaal, met onafhankelijke evaluatie en persistentie. Ze meet geen taalmodel en bewijst geen algemene intelligentie.</p><ul>{limitations}</ul><p>Deze leesprimitieven zijn geen volledige CSV- of productieparser. Een ontbrekende regressie op deze voorbeelden is geen garantie voor andere invoer.</p></details>
<footer>Seed: {result["seed"]} · Dataset SHA-256: {esc(result["fixture_sha256"])}<br>Bewijsbestanden: report.json · fixtures.json · journal.json · experience.sqlite3 · manifest.json</footer>
</main><script>const btn=document.getElementById('filter');btn.addEventListener('click',()=>{{const filtered=btn.getAttribute('aria-pressed')!=='true';btn.setAttribute('aria-pressed',String(filtered));btn.textContent=filtered?'Toon alle gevallen':'Toon alleen verbeterde gevallen';document.querySelectorAll('tbody tr').forEach(row=>row.hidden=filtered&&row.dataset.changed!=='true');}});</script></body></html>'''
